import{_ as o,c as t,b as s,o as n}from"./app-CpW5lisY.js";const l={};function a(r,e){return n(),t("div",null,e[0]||(e[0]=[s('<p>Now promote your seller products on your Shopify store using the <strong>Sponsored Product feature app</strong> in the <a href="https://marketplace-doc.webkul.com/classic/Introduction/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace App</a></p><h2 id="purpose" tabindex="-1"><a class="header-anchor" href="#purpose"><span>Purpose</span></a></h2><p>This feature app allows the Admin to create plans for the Sellers so that they can promote their product on the Admin Shopify store.</p><p>Now you as an admin can promote your seller products on the Home page, Search, Product, and Collection page.</p><p>Admin can easily create different packages for each of these sections and sellers can buy and use these accordingly.</p><p><strong>Update:</strong> Now admin can also allow sellers to set <strong>product-specific daily budgets</strong> and choose whether it would be Global or page-wise.</p><p>This flow is applicable when <strong>Stripe Usage Charge</strong> is selected as the payment method.</p><p><strong>Note-</strong> Admin can set <strong>Minimum Threshold Budget</strong> restricting sellers from adding daily budget less than the threshold budget.</p><p>You will find more details about it in this blog below.</p><p>Now let&#39;s understand how you can configure and use this app for your Marketplace.</p><h3 id="installation-and-workflow" tabindex="-1"><a class="header-anchor" href="#installation-and-workflow"><span>Installation and Workflow</span></a></h3><p>To enable the feature app, visit the featured apps section of the Multivendor Marketplace for Shopify.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/sponser-1.png" alt="sponser-1"></p><p>Now Activate the &quot;Sponsored Product App&quot; from the feature app section. After that, accept the charges and you are ready to use the app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/dssd-1200x520.png" alt="dssd"></p><p>Once you enable the app, Two new submenus one under the Configuration &quot;Sponsorship Configuration&quot; And the second &quot;Sponsored&quot;.</p><p>For the first you need to go to the Admin Panel &gt;&gt; Configuration &gt;&gt; Sponsorship Configuration</p><p>Here on this page, you will find a button to &quot;Allow your seller to enable sponsorship on product&quot;.</p><p>So by enabling this, you can allow your seller to purchase the packages that the admin has created for their products.</p><p><em>Note: Please don&#39;t enable it before creating any Sponsorship package or cross-checking all details to avoid any sort of conflict between Admin &amp; Seller</em></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/sd-1200x547.png" alt="sd"></p><p>The other configuration will also be visible to the admin by clicking on three dots on the top right corner of the app named &quot;Sponsored&quot; with sub-options as shown below:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/spos-1-1200x622.png" alt="spos-1"></p><h3 id="how-to-create-packages-for-sponsored-products" tabindex="-1"><a class="header-anchor" href="#how-to-create-packages-for-sponsored-products"><span>How to create packages for Sponsored products</span></a></h3><p>Admin can create packages for Sponsored products in the Sponsored list.</p><p>Admin will be able to add sponsored products on the home page, search, product, and collection page.</p><p>Accordingly, admin can also create the packages as shown in the image below</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/12-6-1200x523.png" alt="12-6"></p><p>By selecting edit after clicking on the three dots in action as mentioned in the above image.</p><p>Admin will be able to add/edit the package for that particular page.</p><p>Please refer to the below image to learn about the packaged details that need to be added.</p><p><strong>Note: Up to 5 sponsored sections can be added with a max 10 number of products for each section.</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/132-1200x555.png" alt="132"></p><h3 id="add-sponsored-products-for-sellers" tabindex="-1"><a class="header-anchor" href="#add-sponsored-products-for-sellers"><span>Add Sponsored products for Sellers</span></a></h3><p>Once the Admin set the packages then they can enable the Sponsorship for the products from Product Listing as shown in the image.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/123-1200x566.png" alt="123"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/hjb-1200x682.png" alt="hjb"></p><h3 id="allow-seller-to-enable-sponsorship" tabindex="-1"><a class="header-anchor" href="#allow-seller-to-enable-sponsorship"><span>Allow Seller to Enable Sponsorship</span></a></h3><p>Admin can also allow sellers to activate sponsorship for their products.</p><p>They just need to go to Admin Panel &gt;&gt; Configuration &gt;&gt; Sponsored configuration</p><p>On this page, the admin needs to Enable &quot;ALLOW SELLER TO ENABLE SPONSORSHIP ON PRODUCTS&quot; to let Seller use the packages for their products.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/jsd-1200x394.png" alt="jsd"></p><p>Admin can also check the list of Sponsored Sellers, sponsored products, and sponsored orders.</p><p>On the same page, the admin can select the payment methods to receive the sponsor amount from the seller i.e. Shopify checkout and PayPal.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/12/Screenshot-3-1200x525.png" alt="Screenshot-3"></p><p>Suppose the admin has selected both Shopify checkout and PayPal.</p><p>Now, Seller can select any of the payment methods while enabling sponsorship for the product from:</p><p>The seller panel &gt;&gt; product &gt;&gt; product listing &gt;&gt; click on three dots in front of any product &gt;&gt; click &quot;Enable Sponsorship&quot;</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/12/Screenshot1-1200x528.png" alt="Screenshot1"></p><p>Now, a form will be opened to select the page and payment method. In the payment method.</p><p>The seller can select the Shopify checkout and use wallet amount which will be done through PayPal.</p><p>For example, the seller has selected the &quot;use wallet amount&quot;</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/12/Screenshot2-1200x545.png" alt="Screenshot2"></p><p>Then the seller can add the wallet amount from the sponsored product menu &gt;&gt; click sponsored list and click on the &quot;ADD WALLET AMOUNT&quot; button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/12/Screenshot3-1200x462.png" alt="Screenshot3"></p><p>Once you enable the app, Two new submenus one under the Configuration &quot;Sponsorship Configuration&quot; And the second &quot;Sponsored&quot;.</p><p>When the Admin selects the Sponsored products list.</p><p>They will be able to see all the current sponsored product details on their store.</p><p>Admin can also cancel any sponsorship for the products by clicking on the three dots in the action section.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/spons-1200x561.png" alt="spons"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/vf-1200x417.png" alt="vf"></p><h3 id="admin-sponsored-orders" tabindex="-1"><a class="header-anchor" href="#admin-sponsored-orders"><span>Admin Sponsored Orders</span></a></h3><p>Here on this page admin will get all the order listing for the Sponsored Products and can view all their details.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/5445-1200x559.png" alt="5445"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/dfs-1200x495.png" alt="dfs"></p><h3 id="sponsored-sellers" tabindex="-1"><a class="header-anchor" href="#sponsored-sellers"><span>Sponsored Sellers</span></a></h3><p>This will show all the sellers list who are using sponsored products.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/cdbjh-1200x508.png" alt="cdbjh"></p><h3 id="seller-side-configuration" tabindex="-1"><a class="header-anchor" href="#seller-side-configuration"><span>Seller Side Configuration</span></a></h3><p>On the Seller Panel, there will also be a new Sponsor Configuration as shown in the below image.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/cn-d-1200x559.png" alt="cn-d"></p><h3 id="enable-sponsorship-on-product" tabindex="-1"><a class="header-anchor" href="#enable-sponsorship-on-product"><span>Enable Sponsorship on Product</span></a></h3><p>If the admin has enabled &quot;Allow your seller to enable sponsorship on product&quot; then Seller will be able to Enable Sponsorship on their product from the Product listing page.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/f32-1200x543.png" alt="f32"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/dfd-1200x481.png" alt="dfd"></p><h3 id="seller-sponsored-products" tabindex="-1"><a class="header-anchor" href="#seller-sponsored-products"><span>Seller Sponsored Products</span></a></h3><p>When the seller selects <strong>Sponsored Products</strong> from Sponsored Configuration. They will be redirected to this page where they can check all their current sponsored products and their details.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/fdjbhd-1200x473.png" alt="fdjbhd"></p><h3 id="close-sponsorship" tabindex="-1"><a class="header-anchor" href="#close-sponsorship"><span>Close Sponsorship</span></a></h3><p>The seller can also close sponsorship from here by Clicking on &quot;Three dots&quot; in front of the product.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/bhebw-1200x433.png" alt="bhebw"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/ooo-1200x260.png" alt="ooo"></p><h3 id="wallet-amount" tabindex="-1"><a class="header-anchor" href="#wallet-amount"><span>Wallet Amount</span></a></h3><p>When the seller closes any sponsorship before its end date then the remaining day&#39;s amount will be added to their wallet amount.</p><p>This wallet amount they can only use to enable other sponsorships for their products sponsorship.</p><p>And only the refunded amount will be added to the wallet admin can&#39;t add any extra amount on their own.</p><h3 id="sponsor-list" tabindex="-1"><a class="header-anchor" href="#sponsor-list"><span>Sponsor List</span></a></h3><p>Here seller will be able to check it overall paid amount and current wallet amount as well as all sponsorship packages along with sponsor product details.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/hbdjsb-1200x526.png" alt="hbdjsb"></p><h3 id="seller-sponsored-orders" tabindex="-1"><a class="header-anchor" href="#seller-sponsored-orders"><span>Seller Sponsored Orders</span></a></h3><p>Here on this page, Sellers will be able to sponsor product order listing and by clicking on &quot;Three Dot &quot; and selecting view they will be able to view full details of the sponsorship for that order.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/43r-1200x510.png" alt="43r"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/dsscv-1200x433.png" alt="dsscv"></p><h3 id="workflow-when-using-stripe-usage-charge-as-the-payment-method" tabindex="-1"><a class="header-anchor" href="#workflow-when-using-stripe-usage-charge-as-the-payment-method"><span>Workflow when using Stripe Usage Charge as the payment method</span></a></h3><p>The workflow for the sponsorship feature when using stripe usage charge will be as follows:</p><h3 id="admin-panel" tabindex="-1"><a class="header-anchor" href="#admin-panel"><span>Admin Panel:</span></a></h3><ul><li>Admin has to choose “Stripe Usage Charge” as the payment method.</li><li>Then he has to enter the “Stripe Publish Key” and “Stripe Secret Key”.</li><li>Then he has to choose the Billing Cycle, whether it would be weekly or monthly.</li><li>He can choose on which day of the week  the weekly/monthly invoice should be generated</li><li>Admin can choose whether the Minimum Threshold budget should be Global or Page wise.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/11/sponsoredproducts-923x1024.webp" alt="Sponsored products configuration"></p><p>Admin can also allow sellers to set <strong>product-specific daily budgets</strong> and choose whether it would be Global or page-wise.</p><p>If the admin selects page-wise, he can navigate to the Sponsored list and set the page-wise budget.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/11/pagewisebudget-1200x575.webp" alt="page wsie budget"></p><p>If the admin sets it to Global, he can set the threshold budget there only.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/11/adminpanelglobalbudget-1200x575.webp" alt="global threshold budget"></p><h3 id="seller-panel" tabindex="-1"><a class="header-anchor" href="#seller-panel"><span>Seller Panel:</span></a></h3><p>In the Seller Panel, the seller has to add the billing and card details under Sponsor Payment Details.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/11/sellercarddetails-1200x575.webp" alt="Seller Payment Details"></p><p>After updating payment details, the seller can select a product in the <strong>Product Listing</strong> and set a <strong>sponsorship budget</strong> to enable sponsorship for that specific product.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/11/sellerbudget-1.webp" alt="Seller daily budget"></p><p>The budget set by the seller would be treated as a daily spent budget, and it would be product-specific.</p><p><strong>For example</strong>, if a seller sets a budget of 15 USD for a product, then 15 USD will be charged per day, and the bill will be generated weekly on Fridays.</p><p>So, the total amount generated will be 15 * (number of days). This would work as a recurring charge, and the sponsorship will continue indefinitely unless the seller manually stops it.</p><p>For sellers to download their receipts/invoices, they can go to the &quot;Sponsor Order&quot; section in the Seller dashboard. From there, they can view the details on the &quot;Sponsor Order Description&quot; page.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/11/invoice-1200x575.webp" alt="sponsorship invoice"></p><h3 id="how-to-configure-frontend-to-show-sponsored-products" tabindex="-1"><a class="header-anchor" href="#how-to-configure-frontend-to-show-sponsored-products"><span>How to Configure frontend to show Sponsored Products</span></a></h3><p>To Show the sponsored products you need to add the sections for that particular page from the Shopify backend.</p><p>So admin will need to go to Shopify Admin Panel &gt;&gt; Online Store &gt;&gt; Themes &gt;&gt; Current theme &gt;&gt; Click on the Customize button as shown in the below image.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/csu-1200x491.png" alt="csu"></p><p>On the redirected page Admin will get an option of adding a section where the sponsored section will be listed as well. Please refer to the below image.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/fgf-1200x724.png" alt="fgf"></p><p>Once the admin adds the section it will show like this.</p><h3 id="for-normal-type" tabindex="-1"><a class="header-anchor" href="#for-normal-type"><span>For Normal Type</span></a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/re-1200x630.png" alt="re"></p><h3 id="for-scroll-type" tabindex="-1"><a class="header-anchor" href="#for-scroll-type"><span>For Scroll Type</span></a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/09/ds.png" alt="ds"></p><h3 id="demo-details" tabindex="-1"><a class="header-anchor" href="#demo-details"><span>Demo Details</span></a></h3><p>Use the below link and credentials to check the demo of the Sponsored Product Feature App here: <a href="https://sponsor-seller-product.myshopify.com/" target="_blank" rel="noopener noreferrer">https://sponsor-seller-product.myshopify.com/</a></p><p>Store Password: 1</p>',127)]))}const d=o(l,[["render",a]]),i=JSON.parse('{"path":"/classic/Featured-App/Marketplace%20Product%20Add-Ons/SPONSORED%20PRODUCT.html","title":"SPONSORED PRODUCT","lang":"en-US","frontmatter":{"title":"SPONSORED PRODUCT","description":"SPONSORED PRODUCT","date":"2025-08-07T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":2,"title":"Purpose","slug":"purpose","link":"#purpose","children":[{"level":3,"title":"Installation and Workflow","slug":"installation-and-workflow","link":"#installation-and-workflow","children":[]},{"level":3,"title":"How to create packages for Sponsored products","slug":"how-to-create-packages-for-sponsored-products","link":"#how-to-create-packages-for-sponsored-products","children":[]},{"level":3,"title":"Add Sponsored products for Sellers","slug":"add-sponsored-products-for-sellers","link":"#add-sponsored-products-for-sellers","children":[]},{"level":3,"title":"Allow Seller to Enable Sponsorship","slug":"allow-seller-to-enable-sponsorship","link":"#allow-seller-to-enable-sponsorship","children":[]},{"level":3,"title":"Admin Sponsored Orders","slug":"admin-sponsored-orders","link":"#admin-sponsored-orders","children":[]},{"level":3,"title":"Sponsored Sellers","slug":"sponsored-sellers","link":"#sponsored-sellers","children":[]},{"level":3,"title":"Seller Side Configuration","slug":"seller-side-configuration","link":"#seller-side-configuration","children":[]},{"level":3,"title":"Enable Sponsorship on Product","slug":"enable-sponsorship-on-product","link":"#enable-sponsorship-on-product","children":[]},{"level":3,"title":"Seller Sponsored Products","slug":"seller-sponsored-products","link":"#seller-sponsored-products","children":[]},{"level":3,"title":"Close Sponsorship","slug":"close-sponsorship","link":"#close-sponsorship","children":[]},{"level":3,"title":"Wallet Amount","slug":"wallet-amount","link":"#wallet-amount","children":[]},{"level":3,"title":"Sponsor List","slug":"sponsor-list","link":"#sponsor-list","children":[]},{"level":3,"title":"Seller Sponsored Orders","slug":"seller-sponsored-orders","link":"#seller-sponsored-orders","children":[]},{"level":3,"title":"Workflow when using Stripe Usage Charge as the payment method","slug":"workflow-when-using-stripe-usage-charge-as-the-payment-method","link":"#workflow-when-using-stripe-usage-charge-as-the-payment-method","children":[]},{"level":3,"title":"Admin Panel:","slug":"admin-panel","link":"#admin-panel","children":[]},{"level":3,"title":"Seller Panel:","slug":"seller-panel","link":"#seller-panel","children":[]},{"level":3,"title":"How to Configure frontend to show Sponsored Products","slug":"how-to-configure-frontend-to-show-sponsored-products","link":"#how-to-configure-frontend-to-show-sponsored-products","children":[]},{"level":3,"title":"For Normal Type","slug":"for-normal-type","link":"#for-normal-type","children":[]},{"level":3,"title":"For Scroll Type","slug":"for-scroll-type","link":"#for-scroll-type","children":[]},{"level":3,"title":"Demo Details","slug":"demo-details","link":"#demo-details","children":[]}]}],"git":{"updatedTime":1754980561000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"37f2314009fee79d29844e3f75421b31d97c7c49","time":1754980561000,"email":"pratik@webkul.com","author":"pratik","message":"add some more doc"}]},"filePathRelative":"classic/Featured-App/Marketplace Product Add-Ons/SPONSORED PRODUCT.md"}');export{d as comp,i as data};
